namespace Bmd.Tests.Devices.Atem;

/// <summary>The state dump a real Blackmagic ATEM Television Studio HD III sent on connect,
/// captured read-only on 2026-08-30 (handshake and protocol-required ACKs only).
///
/// This is the milestone's ground truth. Blackmagic does not publish the ATEM wire protocol, so
/// a fixture hand-written from community documentation would only prove that our parser and our
/// reading of those documents agree — which is exactly the failure this capture exists to
/// prevent. It already contains three things the documentation does not: an over-long PrvI
/// block, block bytes 2-3 that are 0x0014 rather than reserved-zero, and uninitialised buffer
/// garbage in the padding after a name's terminating NUL (input 2's padding contains a stray
/// "MPrp").
///
/// It cannot be re-captured without hardware access. Treat it as read-only.</summary>
public static class AtemFixtures
{
    // Packets 1-5 carry the 287 command blocks; 6-19 are 12-byte keepalives, two of them
    // Resend retransmissions the switcher sent when the capture was slow to acknowledge.
    static readonly string[] Hex =
    [
        "",
        "",
        "",
        "",
        "",
        "880c80040000000000000006",
        "880c80040000000000000007",
        "280c80040000000000000007",
        "880c80040000000000000008",
        "880c80040000000000000009",
        "880c8004000000000000000a",
        "880c8004000000000000000b",
        "280c8004000000000000000b",
        "880c8004000000000000000c",
        "880c8004000000000000000d",
        "880c8004000000000000000e",
        "880c8004000000000000000f",
        "880c80040000000000000010",
        "880c80040000000000000011",
    ];

    public static IReadOnlyList<byte[]> StateDumpPackets { get; } =
        [.. Hex.Select(Convert.FromHexString)];

    /// <summary>Just the packets carrying command blocks — everything longer than a bare header.</summary>
    public static IReadOnlyList<byte[]> DataPackets { get; } =
        [.. StateDumpPackets.Where(p => p.Length > 12)];
}
